function AutoChessMode.prototype.recreatePlayerPieces(self, playerId)
    local playerState = self.gameState.playerStates:get(playerId)
    if not playerState then
        print(("[AutoChessMode] 警告: 玩家 " .. tostring(playerId)) .. " 状态不存在")
        return
    end
    print(("[AutoChessMode] ========== 重新创建玩家 " .. tostring(playerId)) .. " 的棋子 ==========")
    local benchPieces = playerState.benchPieces or ({})
    local boardPieces = playerState.boardPieces or ({})
    print("[AutoChessMode] 🔍 DEBUG: benchPieces.length = " .. tostring(#benchPieces))
    print("[AutoChessMode] 🔍 DEBUG: boardPieces.length = " .. tostring(#boardPieces))
    if #benchPieces > 0 then
        do
            local i = 0
            while i < #benchPieces do
                local p = benchPieces[i + 1]
                print(((((("[AutoChessMode] 🔍 DEBUG: benchPieces[" .. tostring(i)) .. "] = ") .. p.displayName) .. "(") .. p.id) .. ")")
                i = i + 1
            end
        end
    end
    self.battleSystem:clearPlayerPieces(playerId)
    if #boardPieces > 0 then
        print(("[AutoChessMode] 从棋盘位置恢复 " .. tostring(#boardPieces)) .. " 个棋子")
        do
            local i = 0
            while i < #boardPieces do
                local piece = boardPieces[i + 1]
                local position = {
                    x = 1 + i % 7,
                    y = 1 + math.floor(i / 7)
                }
                print(((((((("[AutoChessMode] 恢复棋盘棋子: " .. piece.displayName) .. "(") .. piece.id) .. ") 到位置 (") .. tostring(position.x)) .. ", ") .. tostring(position.y)) .. ")")
                self.battleSystem:deployPiece(playerId, piece.id, position)
                i = i + 1
            end
        end
    else
        if #benchPieces > 0 then
            print(("[AutoChessMode] 从备战席恢复 " .. tostring(#benchPieces)) .. " 个棋子")
            self:deployPiecesFromBench(playerId)
        else
            print(((((("[AutoChessMode] ⚠️ 警告: 玩家 " .. tostring(playerId)) .. " 没有棋子（benchPieces=") .. tostring(#benchPieces)) .. ", boardPieces=") .. tostring(#boardPieces)) .. "），创建默认棋子")
            self:createDefaultInitialPieces(playerId)
        end
    end
    print(("[AutoChessMode] ========== 玩家 " .. tostring(playerId)) .. " 棋子重新创建完成 ==========")
end
