        if ____cond227 then
            chances:set(____exports.ChessRarity.COMMON, 70)
            chances:set(____exports.ChessRarity.UNCOMMON, 30)
            break
        end
        ____cond227 = ____cond227 or ____switch227 == 3
        if ____cond227 then
            chances:set(____exports.ChessRarity.COMMON, 60)
