        "WAIT_FOR_PLAYERS_TO_LOAD",
        "CUSTOM_GAME_SETUP",
        "HERO_SELECTION",
        "STRATEGY_TIME",
        "PRE_GAME",
        "GAME_IN_PROGRESS",
        "POST_GAME",
        "DISCONNECT",
        "TEAM_SHOWCASE",
